def apply_gva_valid(h, spec):
    """Mutate the GlobalVolumeAccumulator account itself: discriminator,
    owner, lamports, whole data, or individual fields (start/end/
    seconds/mint) -- the #83/#84/#85/#86 validation surface, now
    applied to the account the sync and claim legs read. Runs after
    setup_vm seeding (and after build_route, which never touches
    GVOL). A 0-lamport set makes the account vanish from the VM,
    exactly like #85's 0-lamport pool."""
    if not spec:
        return
    a = h.vm.get_account(GVOL)
    if a is None:
        return
    raw = bytearray(a.data)
    lam, own = a.lamports, a.owner
    if "data" in spec:
        if spec["data"] == "zero":
            raw = bytearray(len(raw))
        else:
            srcmap = {"pool": pool, "config": CONFIG_KEY, "fee": feeconfig,
                      "uva": volume}
            sa = h.vm.get_account(srcmap[spec["data"]]) if spec["data"] in srcmap else None
            if sa is not None:
                raw = bytearray(bytes(sa.data)[:len(raw)].ljust(len(raw), b'\0'))
    if "disc" in spec:
        if spec["disc"] == "zero":
            raw[0:8] = bytes(8)
        elif spec["disc"] == "flip":
            raw[0] ^= 0xFF
        else:
            srcmap = {"pool": pool, "config": CONFIG_KEY, "fee": feeconfig,
                      "uva": volume}
            sa = h.vm.get_account(srcmap[spec["disc"]]) if spec["disc"] in srcmap else None
            if sa is not None:
                raw[0:8] = bytes(sa.data)[:8]
    if "owner" in spec:
        own = {"program": PROGRAM, "token": TOKEN, "token22": TOKEN22,
               "fees": FEES_PROG,
               "sys": Pubkey.from_string("11111111111111111111111111111111"),
               "default": Pubkey.default()}[spec["owner"]]
    if "lamports" in spec:
        lam = spec["lamports"]
    if "start" in spec:
        struct.pack_into('<q', raw, 8, spec["start"])
    if "end" in spec:
        struct.pack_into('<q', raw, 16, spec["end"])
    if "seconds" in spec:
        struct.pack_into('<q', raw, 24, spec["seconds"])
    if "mint" in spec:
        raw[32:64] = {"quote": bytes(quote), "base": bytes(base),
                      "zero": bytes(32), "imint": bytes(IMINT)}[spec["mint"]]
    h.vm.set_account(GVOL, Account(lam, bytes(raw), own))



VAULT_KEYS = {"vb1": vaultbase, "vq1": vaultquote, "vb2": VB2, "vq2": VQ2,
              "vb3": VB3, "vq3": VQ3, "userquote": userquote,
              "userbase": userbase, "userlp": userlp, "u3": U3,
              "bb22": BB22, "proto22": PROTO22, "creat22": CREAT22,
              "dest22": DEST22}
SYS_PROG = Pubkey.from_string("11111111111111111111111111111111")


def apply_vault_valid(h, spec):
    """Mutate a vault / token account itself: mint, ATA owner,
    owning program, lamports, amount, state, or whole data.
    Token accounts have no discriminator: mint is bytes 0:32,
    ATA owner is bytes 32:64, amount is u64 at 64, state is byte
    108 (0 uninitialized, 1 initialized, 2 frozen). Runs AFTER
    build_route: route2/three_amm overwrite VB2/VQ2/VB3/VQ3, so
    an earlier mutation would be clobbered. For the main vaults
    (vaultbase/vaultquote) and user accounts the order does not
    matter, but running after routes keeps one rule for all."""
    if not spec:
        return
    key = VAULT_KEYS[spec["acct"]]
    a = h.vm.get_account(key)
    if a is None:
        return
    raw = bytearray(a.data)
    lam, own = a.lamports, a.owner
    if "data" in spec:
        sa = h.vm.get_account(VAULT_KEYS[spec["data"]])
        if sa is not None:
            raw = bytearray(bytes(sa.data)[:len(raw)].ljust(len(raw), b"\0"))
    if "mint" in spec:
        raw[0:32] = {"quote": bytes(quote), "base": bytes(base),
                     "base2": bytes(BASE2), "base3": bytes(BASE3),
                     "zero": bytes(32), "imint": bytes(IMINT),
                     "lp": bytes(lp)}[spec["mint"]]
    if "owner_acct" in spec:
        raw[32:64] = {"payer": bytes(PAYER_KEY), "outsider": bytes(OUTSIDER_KEY),
                      "creator": bytes(CREATOR), "creator_vault": bytes(CREATOR_VAULT),
                      "protocol": bytes(PROTOCOL), "zero": bytes(32),
                      "pool": bytes(pool)}[spec["owner_acct"]]
    if "amount" in spec:
        struct.pack_into("<Q", raw, 64, spec["amount"])
    if "state" in spec:
        raw[108] = spec["state"]
    if "owner_prog" in spec:
        own = {"token": TOKEN, "token22": TOKEN22, "sys": SYS_PROG,
               "default": Pubkey.default(), "program": PROGRAM}[spec["owner_prog"]]
    if "lamports" in spec:
        lam = spec["lamports"]
    h.vm.set_account(key, Account(lam, bytes(raw), own))


POOLKEYS = {"main": pool, "p2": POOL2, "p3": P3, "p4": P4, "p5": P5}


def apply_cfg_patch(h, patch):
    """Patch stored authority values in GlobalConfig: admin (8..40),
    admin_set_coin_creator_authority (321..353), boost authority
    (907..939), boost enabled (939). Runs after setup_vm, which
    presets boost authority to the payer."""
    if not patch:
        return
    a = h.vm.get_account(CONFIG_KEY)
    raw = bytearray(a.data)
    if "admin" in patch:
        raw[8:40] = bytes(patch["admin"])
    if "cto_auth" in patch:
        raw[321:353] = bytes(patch["cto_auth"])
    if "boost_auth" in patch:
        raw[907:939] = bytes(patch["boost_auth"])
    if "boost_enabled" in patch:
        raw[939] = patch["boost_enabled"]
    h.vm.set_account(CONFIG_KEY, Account(a.lamports, bytes(raw), a.owner))


def apply_pool_creator(h, key):
    """Patch the main pool's creator field (11..43 -- Pool.creator,
    the field multi_hop_swap.rs:499 and set_coin_creator.rs compare
    against the [pool-authority, base_mint] PDA; NOT 211..243, which
    is coin_creator). A creator that is not the PDA must fail
    set_coin_creator (6028) and multi-hop entry (6078). Runs after
    build_route. NOTE: the harness snapshot field named
    "pool_creator" reads bytes 211..243 (coin_creator), so it does
    not reflect this patch; the patch itself is verified by the
    gate outcomes below."""
    if key is None:
        return
    a = h.vm.get_account(pool)
    d = bytearray(a.data)
    d[11:43] = bytes(key)
    h.vm.set_account(pool, Account(a.lamports, bytes(d), a.owner))


def setup_stable(h):
    usdc_data = (b"\0" * 4 + b"\0" * 32 + struct.pack("<Q", 10**15) + bytes([6, 1])
                 + b"\0" * 36)
    h.vm.set_account(USDC, Account(10**9, usdc_data, TOKEN))
    for pool_key, bump, creator, bm, qm, vb, vq in (
            (P2S, B2S, C_USDC, USDC, base, VB2S, VQ2S),
            (P3S, B3S, C3, BASE3, USDC, VB3S, VQ3S)):
        d = bytearray(poolraw)
        d[8] = bump
        d[9:11] = bytes(2)
        d[11:43] = bytes(creator)
        d[43:75] = bytes(bm)
        d[75:107] = bytes(qm)
        d[139:171] = bytes(vb)
        d[171:203] = bytes(vq)
        h.vm.set_account(pool_key, Account(10**9, bytes(d), PROGRAM))
        h.vm.set_account(vb, Account(10**9, token(bm, pool_key, 10**15), TOKEN))
        h.vm.set_account(vq, Account(10**9, token(qm, pool_key, 10**15), TOKEN))
    h.vm.set_account(PROTO_ATA_S, Account(10**9, token(USDC, PROTOCOL, 0), TOKEN))
    h.vm.set_account(CREAT_ATA_S, Account(10**9, token(USDC, CREATOR_VAULT, 0), TOKEN))
    h.vm.set_account(DEST_S, Account(10**9, token(USDC, CREATOR, 0), TOKEN))


def build_route_stable(h, sell):
    metas = build_route(h, sell)
    g2s = [AccountMeta(USDC, False, False), AccountMeta(base, False, False),
           AccountMeta(P2S, False, True), AccountMeta(VB2S, False, True),
           AccountMeta(VQ2S, False, True)]
    g3s = [AccountMeta(BASE3, False, False), AccountMeta(USDC, False, False),
           AccountMeta(P3S, False, True), AccountMeta(VB3S, False, True),
           AccountMeta(VQ3S, False, True)]
    # Standard TRUE 3-hop layout from build_route: buy = fixed16 + main
    # (16..20) + POOL2 (21..25) + P3 (26..30); sell = fixed16 + P3
    # (16..20) + POOL2 (21..25) + main (26..30). The stable route keeps
    # the main group and swaps the POOL2/P3 groups for P2S/P3S, so the
    # route is still 3 hop groups, final output U3 (m[1] sell / m[2] buy
    # already set to U3 by three_amm).
    if sell:
        return metas[:16] + g3s + g2s + metas[26:31]
    return metas[:21] + g2s + g3s


def build_route_1hop(h, sell):
    keys = MH_KEYS_SELL if sell else MH_KEYS_BUY
    ix = next(x for x in IDL["instructions"] if x["name"] == "multi_hop_swap")
    metas = [AccountMeta(k, bool(a.get("signer")), bool(a.get("writable")))
             for k, a in zip(keys, ix["accounts"])] + list(MH_TAIL)
    # Unused hop pools sit at the INIT state so snapshots stay complete.
    for pk in (POOL2, P3, P4, P5):
        h.vm.set_account(pk, Account(10**9, bytes(poolraw), PROGRAM))
    return metas


def snap(vm):
    out = {}
    for k in WATCH:
        a = vm.get_account(k)
        out[str(k)] = None if a is None else {
            "lamports": a.lamports, "owner": str(a.owner),
            "data_hex": bytes(a.data).hex()}
    return out


def tok_amount(entry):
    if entry is None:
        return None
    raw = bytes.fromhex(entry["data_hex"])
    return struct.unpack_from("<Q", raw, 64)[0] if len(raw) >= 72 else None


def tok_delta(rec, key):
    b = rec["before"][str(key)]
    a = rec["after"][str(key)]
    return (tok_amount(a) or 0) - (tok_amount(b) or 0)


def wh_of(entry):
    if entry is None:
        return None
    raw = bytes.fromhex(entry["data_hex"])
    if len(raw) == 178:
        return struct.unpack_from("<Q", raw, 170)[0]
    if len(raw) == 182:
        return struct.unpack_from("<Q", raw, 174)[0]
    return None


def wh_delta(rec, key):
    b = rec["before"][str(key)]
    a = rec["after"][str(key)]
    return (wh_of(a) or 0) - (wh_of(b) or 0)


def mint_wh(entry):
    if entry is None:
        return None
    raw = bytes.fromhex(entry["data_hex"])
    return struct.unpack_from("<Q", raw, 234)[0] if len(raw) >= 242 else None


def lam_delta(rec, key):
    b = rec["before"][str(key)]
    a = rec["after"][str(key)]
    return (a["lamports"] if a else 0) - (b["lamports"] if b else 0)


def pool_state(entry):
    if entry is None:
        return None
    d = bytes.fromhex(entry["data_hex"])
    return [int.from_bytes(d[245:261], "little", signed=True),
            struct.unpack_from("<Q", d, 271)[0],
            struct.unpack_from("<Q", d, 279)[0],
            struct.unpack_from("<Q", d, 203)[0]]


def cfg_fields(entry):
    if entry is None:
        return None
    raw = bytes.fromhex(entry["data_hex"])
    if len(raw) < 949:
        return {"len": len(raw)}
    return {"admin": raw[8:40].hex(), "disable": raw[56], "lp": u64(raw, 40), "proto": u64(raw, 48),
            "recipients": [raw[57 + i * 32:57 + (i + 1) * 32].hex() for i in range(8)],
            "creator_fee": u64(raw, 313), "fee_auth": raw[321:353].hex(),
            "bps": u64(raw, 899),
            "bb_recipients": [raw[643 + i * 32:643 + (i + 1) * 32].hex() for i in range(8)],
            "mayhem": raw[417], "cashback": raw[642],
            "boost_auth": raw[907:939].hex(), "boost_enabled": raw[939]}


def vol_state(entry):
    if entry is None:
        return None
    raw = bytes.fromhex(entry["data_hex"])
    return {"lamports": entry["lamports"], "len": len(raw),
            "user": raw[8:40].hex()}


def uva_fields(entry):
    if entry is None:
        return None
    raw = bytes.fromhex(entry["data_hex"])
    if len(raw) < 90:
        return {"len": len(raw)}
    needs, unc, cla, vol, last, hasc, earn, cbcl = struct.unpack_from('<BQQQqBQQ', raw, 40)
    return {"needs": needs, "unclaimed": unc, "claimed": cla, "volume": vol,
            "last": last, "has": hasc, "earned": earn, "cb_claimed": cbcl}


def gva_fields(entry):
    if entry is None:
        return None
    raw = bytes.fromhex(entry["data_hex"])
    if len(raw) < 544:
        return {"len": len(raw)}
    start, end, seconds = struct.unpack_from('<qqq', raw, 8)
    supply0, = struct.unpack_from('<Q', raw, 64)
    sol0, = struct.unpack_from('<Q', raw, 304)
    supply29, = struct.unpack_from('<Q', raw, 296)
    sol29, = struct.unpack_from('<Q', raw, 536)
    return {"lamports": entry["lamports"], "len": len(raw),
            "start": start, "end": end, "seconds": seconds,
            "mint": raw[32:64].hex(), "supply0": supply0, "sol0": sol0,
            "supply29": supply29, "sol29": sol29}


def ev_list(logs):
    out = []
    for l in logs:
        if l.startswith("Program data: "):
            raw = base64.b64decode(l.split("Program data: ", 1)[1].strip())
            out.append(raw)
    return out


def u64(raw, off):
    return struct.unpack_from("<Q", raw, off)[0]


def decode_event(kind, raw):
    if kind == "ww":
        return None
    if kind in ("mhbuy3", "mhbuy5", "mhbuy4", "mhbuy1", "stbuy3"):
        return {"disc": raw[:8].hex(), "len": len(raw),
                "ts": struct.unpack_from("<q", raw, 8)[0],
                "base": u64(raw, 16), "quote": u64(raw, 24)}
    if kind in ("mhsell3", "mhsell5", "mhsell4", "mhsell1", "stsell3"):
        return {"disc": raw[:8].hex(), "len": len(raw),
                "ts": struct.unpack_from("<q", raw, 8)[0],
                "base": u64(raw, 16), "quote_gross": u64(raw, 104),
                "quote": u64(raw, 112)}
    if kind in ("swp", "swc"):
        return {"disc": raw[:8].hex(), "len": len(raw),
                "timestamp": struct.unpack_from("<q", raw, 8)[0],
                "recipient": raw[112:144].hex(),
                "amount": u64(raw, 176), "bucket": raw[184]}
    if kind == "uadm":
        return {"disc": raw[:8].hex(), "len": len(raw),
                "ts": struct.unpack_from("<q", raw, 8)[0],
                "old": raw[16:48].hex(), "new": raw[48:80].hex()}
    if kind in ("dep", "wd"):
        return {"disc": raw[:8].hex(), "len": len(raw),
                "base": u64(raw, 72), "quote": u64(raw, 80)}
    if kind == "col":
        return {"disc": raw[:8].hex(), "len": len(raw),
                "timestamp": struct.unpack_from("<q", raw, 8)[0],
                "creator": raw[16:48].hex(), "fee": u64(raw, 48),
                "vault_ata": raw[56:88].hex(), "dest": raw[88:120].hex()}
    if kind == "boost":
        if raw[:8].hex() != BST_DISC:
            return {"disc": raw[:8].hex(), "len": len(raw)}
        return {"disc": raw[:8].hex(), "len": len(raw),
                "requested": u64(raw, 144), "used": u64(raw, 152),
                "burned": u64(raw, 160),
                "vq": int.from_bytes(raw[168:184], "little", signed=True),
                "quote_after": u64(raw, 184), "base_after": u64(raw, 192),
                "remaining": u64(raw, 200)}
    if kind in ("close", "close_other", "close_unsigned"):
        return {"disc": raw[:8].hex(), "user": raw[8:40].hex(),
                "ts": struct.unpack_from("<q", raw, 40)[0],
                "unc": u64(raw, 48), "claimed": u64(raw, 56),
                "vol": u64(raw, 64), "last": struct.unpack_from("<q", raw, 72)[0],
                "len": len(raw)}
    if kind == "init":
        return {"disc": raw[:8].hex(), "payer": raw[8:40].hex(),
                "user": raw[40:72].hex(),
                "ts": struct.unpack_from("<q", raw, 72)[0], "len": len(raw)}
    if kind == "sync":
        return {"disc": raw[:8].hex(), "user": raw[8:40].hex(),
                "before": u64(raw, 40), "after": u64(raw, 48),
                "ts": struct.unpack_from("<q", raw, 56)[0], "len": len(raw)}
    if kind in ("extend", "extend_unsigned", "extend_readonly"):
        return {"disc": raw[:8].hex(),
                "ts": struct.unpack_from("<q", raw, 8)[0],
                "account": raw[16:48].hex(), "user": raw[48:80].hex(),
                "old": u64(raw, 80), "new": u64(raw, 88), "len": len(raw)}
    if kind == "tclaim":
        return {"disc": raw[:8].hex(), "len": len(raw),
                "user": raw[8:40].hex(), "mint": raw[40:72].hex(),
                "amount": u64(raw, 72), "ts": struct.unpack_from("<q", raw, 80)[0],
                "total_claimed": u64(raw, 88), "current_sol_volume": u64(raw, 96)}
    if kind == "cclaim":
        return {"disc": raw[:8].hex(), "len": len(raw),
                "user": raw[8:40].hex(), "amount": u64(raw, 40),
                "ts": struct.unpack_from("<q", raw, 48)[0],
                "total_claimed": u64(raw, 56), "total_earned": u64(raw, 64)}
    if kind == "ufc":
        return {"disc": raw[:8].hex(), "len": len(raw),
                "admin": raw[16:48].hex(), "lp": u64(raw, 48), "proto": u64(raw, 56),
                "recipients": [raw[64 + i * 32:64 + (i + 1) * 32].hex() for i in range(8)],
                "creator": u64(raw, 320), "authority": raw[328:360].hex()}
    if kind == "dis":
        return {"disc": raw[:8].hex(), "len": len(raw),
                "ts": struct.unpack_from("<q", raw, 8)[0],
                "admin": raw[16:48].hex(),
                "bools": [raw[48 + i] for i in range(5)]}
    if kind == "set":
        return {"disc": raw[:8].hex(), "len": len(raw),
                "creator": raw[112:144].hex()}
    if kind == "mig":
        return {"disc": raw[:8].hex(), "len": len(raw),
                "old": raw[112:144].hex(), "new": raw[144:176].hex()}
    if kind == "buy2":
        return {"disc": raw[:8].hex(), "len": len(raw),
                "curve": u64(raw, 64), "lp_bps": u64(raw, 72),
                "lp_fee": u64(raw, 80), "proto_bps": u64(raw, 88),
                "proto_fee": u64(raw, 96), "qwlp": u64(raw, 104),
                "uin": u64(raw, 112)}
    if kind == "sell2":
        return {"disc": raw[:8].hex(), "len": len(raw),
                "curve": u64(raw, 64), "lp_bps": u64(raw, 72),
                "lp_fee": u64(raw, 80), "proto_bps": u64(raw, 88),
                "proto_fee": u64(raw, 96), "quote": u64(raw, 104),
                "uout": u64(raw, 112)}
    if kind in ("legbuy", "legsell"):
        # Legacy BuyEvent (disc 67f4521f2cf57777, len 497) and
        # SellEvent (disc 3e2f370aa503dc2a, len 449) share the
        # multi-hop event discriminators; only disc/len are pinned.
        return {"disc": raw[:8].hex(), "len": len(raw)}
    return None


def check(cond, msg):
    if not cond:
        raise AssertionError(msg)


def disc(name):
    return bytes(next(x for x in IDL["instructions"] if x["name"] == name)["discriminator"])


