        ix = next(x for x in IDL["instructions"] if x["name"] == "sell")
        metas = [AccountMeta(k, bool(a.get("signer")), bool(a.get("writable")))
                 for k, a in zip(leg_keys(args[2]), ix["accounts"])] + list(LEG_REM)
